mapper.update:
UPDATE cw_order
SET logistics_trace = CONCAT(COALESCE(logistics_trace, ''), '→[已加急]')
WHERE order_id = #{orderId}

mapper.select:
SELECT o.order_id, o.user_id, u.username, o.product_id, o.product_name,
       o.amount, o.status, o.receiver_addr, o.created_at_ms
FROM cw_order o
LEFT JOIN cw_user u ON u.id = o.user_id

    AND o.user_id = #{userId}
    AND o.order_id = #{orderId}
    AND o.status = #{status}

        AND u.username LIKE CONCAT('%', #{username}, '%')


ORDER BY o.created_at_ms DESC
